function validate([nums, queries]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value in nums is an integer from 1 to 10^5.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > n) return 'queries needs 1 to nums.length queries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [index, k].';
    const [index, k] = query;
    if (!Number.isInteger(index) || index < 0 || index >= n) return 'Each query index is from 0 to n - 1.';
    if (!Number.isInteger(k) || k < 0 || k >= n) return 'Each query k is from 0 to n - 1.';
  }
  return null;
}

