function unmarkedSumArray(nums, queries) {
  const n = nums.length;
  const order = nums.map((_, i) => i);
  order.sort((a, b) => nums[a] - nums[b] || a - b);
  const marked = new Array(n).fill(false);
  let sum = 0;
  for (const value of nums) {
    sum += value;
  }
  let next = 0;
  const answer = [];
  for (const [index, k] of queries) {
    if (!marked[index]) {
      marked[index] = true;
      sum -= nums[index];
    }
    let toMark = k;
    while (toMark > 0 && next < n) {
      const i = order[next];
      next++;
      if (!marked[i]) {
        marked[i] = true;
        sum -= nums[i];
        toMark--;
      }
    }
    answer.push(sum);
  }
  return answer;
}

