function unmarkedSumArray(nums, queries) {
  const done = nums.map(() => false);
  const result = [];
  for (const [index, k] of queries) {
    done[index] = true;
    for (let step = 0; step < k; step++) {
      let pick = -1;
      for (let i = 0; i < nums.length; i++) {
        if (!done[i] && (pick === -1 || nums[i] < nums[pick])) pick = i;
      }
      if (pick === -1) break;
      done[pick] = true;
    }
    result.push(nums.reduce((acc, v, i) => acc + (done[i] ? 0 : v), 0));
  }
  return result;
}

