function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(1, 8);
  const m = size === 'large' ? int(1000, 2000) : int(1, n);
  const top = rand() < 0.5 ? 100000 : (size === 'large' ? 50 : 4);
  const nums = Array.from({ length: n }, () => int(1, top));
  const queries = Array.from({ length: m }, () => {
    const k = size === 'large' ? (rand() < 0.01 ? int(0, n - 1) : int(0, 1)) : (rand() < 0.3 ? int(0, n - 1) : int(0, 2));
    return [int(0, n - 1), Math.min(k, n - 1)];
  });
  return [nums, queries];
}
